import sys

# Simulación de entry_points para el ejercicio (en real viene de importlib.metadata)
_PLUGINS_INSTALADOS = [
    {'name': 'json', 'group': 'mitool.exporters', 'target': 'json_exporter'},
    {'name': 'csv',  'group': 'mitool.exporters', 'target': 'csv_exporter'},
    {'name': 'roto', 'group': 'mitool.exporters', 'target': 'no_existe'},
]

class _EP:
    def __init__(self, d): self.name, self.group, self._t = d['name'], d['group'], d['target']
    def load(self):
        if self._t == 'no_existe':
            raise ImportError(f'módulo {self._t} no encontrado')
        return type(self._t.title().replace('_',''), (), {'formato': self._t})

def entry_points_simulado(group=None):
    return [_EP(d) for d in _PLUGINS_INSTALADOS if group is None or d['group'] == group]

