def cargar_exportadores():
    registro = {}
    for ep in entry_points_simulado(group='mitool.exporters'):
        try:
            registro[ep.name] = ep.load()
        except Exception as e:
            print(f'plugin {ep.name!r} falló al cargar: {e}', file=sys.stderr)
    return registro

def main(argv=None):
    argv = list(argv or [])
    try:
        exportadores = cargar_exportadores()
    except Exception as e:
        print(f'error cargando plugins: {e}', file=sys.stderr)
        return 1

    if any(a.startswith('--') and a not in ('--version',) for a in argv):
        print('uso: mitool [exportador]', file=sys.stderr)
        return 2

    for nombre in argv:
        if nombre not in exportadores:
            print(f'exportador no encontrado: {nombre}', file=sys.stderr)
            return 1

    print(f'{len(exportadores)} exportadores disponibles')
    return 0

