(pkg/'cleaning.py').write_text('''"""M1.4: normalización de texto y tipos."""
import json, pathlib, re, unicodedata

_ESP = re.compile(r"\\s+")
_NUM = re.compile(r"[\\d.,]+")

def limpiar_texto(s) -> str:
    return _ESP.sub(" ", unicodedata.normalize("NFC", s or "").replace("\\xa0", " ")).strip()

def parsear_precio(txt):
    m = _NUM.search((txt or "").replace(" ", ""))
    if not m: return None
    s = m.group()
    if "," in s and "." in s:
        s = s.replace(".", "").replace(",", ".") if s.rfind(",") > s.rfind(".") else s.replace(",", "")
    elif "," in s:
        s = s.replace(",", ".") if len(s.split(",")[-1]) != 3 else s.replace(",", "")
    try: return float(s)
    except ValueError: return None

def limpiar_archivo(entrada, salida) -> dict:
    raw = json.loads(pathlib.Path(entrada).read_text(encoding="utf-8"))
    limpios, problemas = [], 0
    for r in raw:
        out = {k: (limpiar_texto(v) if isinstance(v, str) else v) for k, v in r.items()}
        if "precio" in out and isinstance(out["precio"], str):
            out["precio"] = parsear_precio(out["precio"])
            if out["precio"] is None: problemas += 1
        limpios.append(out)
    tmp = pathlib.Path(salida).with_suffix(".tmp")
    tmp.write_text(json.dumps(limpios, ensure_ascii=False, indent=2), encoding="utf-8")
    tmp.replace(salida)                      # M1.3-007 escritura atómica
    return {"limpios": len(limpios), "problemas": problemas}
''', encoding='utf-8')

