import json, sqlite3
from importlib.resources import files

def cargar_fuentes() -> dict:
    """Lee data/fuentes.json DESDE DENTRO del paquete (portable)."""
    return json.loads(files("mitoolkit").joinpath("data/fuentes.json").read_text(encoding="utf-8"))

def importar_json(entrada, db_path) -> int:
    regs = json.loads(__import__("pathlib").Path(entrada).read_text(encoding="utf-8"))
    if not regs: return 0
    cols = sorted(regs[0].keys())
    conn = sqlite3.connect(db_path)
    with conn:
        defs = ", ".join(f'"{c}" TEXT' for c in cols if c != "id")
        conn.execute(f'CREATE TABLE IF NOT EXISTS items (id TEXT PRIMARY KEY, {defs})')
        placeholders = ", ".join([":id"] + [f':{c}' for c in cols if c != "id"])
        updates = ", ".join(f'"{c}"=excluded."{c}"' for c in cols if c != "id")
        filas = [{**r, "id": str(r.get("id") or r.get(cols[0]))} for r in regs]
        for f in filas:
            for c in cols:
                if c != "id" and not isinstance(f.get(c), (str, type(None))):
                    f[c] = json.dumps(f[c], ensure_ascii=False)
        conn.executemany(
            f'INSERT INTO items (id, {", ".join(chr(34)+c+chr(34) for c in cols if c != "id")}) '
            f'VALUES ({placeholders}) ON CONFLICT(id) DO UPDATE SET {updates}', filas)
    total = conn.execute("SELECT COUNT(*) FROM items").fetchone()[0]
    conn.close()
    return total
''', encoding='utf-8')

